css:
@page {
    size: A4;
    margin: 1cm;
}

table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
}

th, td {
    border: 1px solid #ccc;
    padding: 8px;
}

th {
    text-align: left;
}

h1 {
    text-align: center;
}

.pending {
    border: 1px solid red;
    padding: 10px;
    text-align: center;
    font-weight: bold;
}

.total {
    margin-top: 20px;
    font-size: 20px;
    font-weight: bold;
    text-align: right;
}

@media print {
    .btn,
    button,
    input,
    select,
    textarea {
        display: none !important;
    }
}
